args.content:
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/property/>
PREFIX geo: <http://www.wikidata.org/ontology/>

SELECT ?item ?label ?latitude ?longitude
WHERE {
  ?item a wd:Q5 (wdt:P31 wd:Q1353771) ;
        wdt:P625 ?geoPoint .
  ?geoPoint geo:lat ?latitude ;
            geo:lon ?longitude .
  FILTER (?item IN (wd:Q8813) || ?item IN (wd:Q29))
  ?item wdt:P1476 ?label .
  FILTER (lang(?label) != "en")
}

